/**
 * Site content that non-developers edit in the Google Sheet. The JSON snapshots are generated by
 * scripts/sheet-sync.mjs (run automatically before every build). Edit the Sheet, not these files.
 * Only `items` is imported so each snapshot's validation notes stay out of the client bundle.
 */
import { items as teamItems } from "./generated/team.json";
import { items as achievementItems } from "./generated/achievements.json";
import { items as placementItems } from "./generated/placements.json";
import { items as settingsItems } from "./generated/settings.json";
import type { AchievementEntry, PlacementEntry, SettingsValues, TeamPerson } from "@/types";

/** Used when the settings tab has no contact_email. */
export const FALLBACK_CONTACT_EMAIL = "mesacusatacademy@gmail.com";

const team = teamItems as TeamPerson[];
const achievements = achievementItems as AchievementEntry[];
const placements = placementItems as PlacementEntry[];
const settings = settingsItems as SettingsValues;

export function getTeam(): TeamPerson[] {
  return team;
}

export interface TeamGroup {
  name: string;
  people: TeamPerson[];
}

/** People grouped by the sheet's `group` column; groups ordered by their lowest `order`, then name. */
export function getTeamGroups(): TeamGroup[] {
  const map = new Map<string, TeamPerson[]>();
  for (const p of team) {
    const list = map.get(p.group) ?? [];
    list.push(p);
    map.set(p.group, list);
  }
  const rank = (people: TeamPerson[]) =>
    Math.min(...people.map((p) => p.order ?? Number.POSITIVE_INFINITY));
  return [...map.entries()]
    .map(([name, people]) => ({ name, people }))
    .sort((a, b) => rank(a.people) - rank(b.people) || a.name.localeCompare(b.name));
}

export function getAchievements(): AchievementEntry[] {
  return achievements;
}

export function getPlacements(): PlacementEntry[] {
  return placements;
}

export interface HomeStat {
  label: string;
  value: string;
}

export interface SiteConfig {
  heroTitle?: string;
  heroSubtitle?: string;
  /** Only stats that have a value in the sheet. */
  stats: HomeStat[];
  contactEmail: string;
  /** Never hardcoded: only present when settings.contact_phone is set. */
  contactPhone?: string;
  instagramUrl?: string;
  linkedinUrl?: string;
  reportFormUrl?: string;
  reportFormFileEntry?: string;
  placementBrochureUrl?: string;
  announcementText?: string;
  announcementLink?: string;
  footerText?: string;
}

export function getSettings(): SiteConfig {
  const s = settings;
  const stat = (key: string, label: string): HomeStat[] =>
    s[key] ? [{ label: s[`${key}_label`] || label, value: s[key] as string }] : [];
  return {
    heroTitle: s.hero_title,
    heroSubtitle: s.hero_subtitle,
    stats: [
      ...stat("stat_members", "Members"),
      ...stat("stat_papers", "Question papers"),
      ...stat("stat_placements", "Placements"),
    ],
    contactEmail: s.contact_email || FALLBACK_CONTACT_EMAIL,
    contactPhone: s.contact_phone,
    instagramUrl: s.instagram_url,
    linkedinUrl: s.linkedin_url,
    reportFormUrl: s.report_form_url,
    reportFormFileEntry: s.report_form_file_entry,
    placementBrochureUrl: s.placement_brochure_url,
    announcementText: s.announcement_text,
    announcementLink: s.announcement_link,
    footerText: s.footer_text,
  };
}
